const menuButton = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
function closeMenu() { navigation.classList.remove('open'); menuButton.setAttribute('aria-expanded', 'false'); menuButton.innerHTML = 'Menu <span>+</span>'; document.body.classList.remove('modal-open'); }
menuButton.addEventListener('click', () => { const open = menuButton.getAttribute('aria-expanded') !== 'true'; navigation.classList.toggle('open', open); menuButton.setAttribute('aria-expanded', String(open)); menuButton.innerHTML = open ? 'Close <span>×</span>' : 'Menu <span>+</span>'; document.body.classList.toggle('modal-open', open); });
navigation.querySelectorAll('a').forEach(link => link.addEventListener('click', closeMenu));
document.addEventListener('keydown', event => { if (event.key === 'Escape' && navigation.classList.contains('open')) { closeMenu(); menuButton.focus(); } if(event.key === 'Tab' && navigation.classList.contains('open')) { const first = navigation.querySelector('a'); if(event.shiftKey && document.activeElement === first) {event.preventDefault();menuButton.focus();} else if(!event.shiftKey && document.activeElement === menuButton) {event.preventDefault();first.focus();} } });
matchMedia('(min-width:701px)').addEventListener('change', event => { if(event.matches) closeMenu(); });
function showDialog(dialog) { dialog.showModal(); document.body.classList.add('modal-open'); }
document.querySelectorAll('[data-open-project]').forEach(button => button.addEventListener('click', () => showDialog(document.querySelector('#project-dialog'))));
document.querySelector('#start-project').addEventListener('click', () => showDialog(document.querySelector('#contact-dialog')));
document.querySelectorAll('dialog').forEach(dialog => { dialog.querySelector('.dialog-close').addEventListener('click', () => dialog.close()); dialog.addEventListener('close', () => document.body.classList.remove('modal-open')); dialog.addEventListener('click', event => { const rect = dialog.getBoundingClientRect(); if(event.target === dialog && (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom)) dialog.close(); }); });
document.querySelector('#brief-form').addEventListener('submit', event => { event.preventDefault(); const brief = document.querySelector('#brief').value.trim(); if(brief.length < 10) { document.querySelector('#brief-status').textContent = 'Add at least 10 characters to your brief.'; return; } const file = new Blob(['WEBLEAN — PROJECT BRIEF\n\n' + brief + '\n'], {type:'text/plain;charset=utf-8'}); const url = URL.createObjectURL(file); const link = document.createElement('a'); link.href = url; link.download = 'weblean-project-brief.txt'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); document.querySelector('#brief-status').textContent = 'Your brief is ready. Nothing has been sent to Weblean.'; });
document.querySelector('#year').textContent = new Date().getFullYear();
const system = document.querySelector('.system');
system.addEventListener('pointermove', event => { if (matchMedia('(prefers-reduced-motion: reduce)').matches) return; const rect = system.getBoundingClientRect(); document.querySelector('.coordinates').textContent = `X ${String(Math.round(event.clientX - rect.left)).padStart(3,'0')} / Y ${String(Math.round(event.clientY - rect.top)).padStart(3,'0')}`; });
